import { parseFormula, refsOf, evaluate } from "./formula.mjs";
import { parseAddr, toAddr, compareAddr } from "./addr.mjs";

export function valueOf(raw) {
  if (raw === "") return null;
  const t = raw.trim();
  if (t !== "" && !/^[+-]?0[xbo]/i.test(t) && Number.isFinite(Number(t))) return Number(t);
  if (/^true$/i.test(raw)) return true;
  if (/^false$/i.test(raw)) return false;
  if (raw.startsWith("'")) return raw.slice(1);
  return raw;
}

const norm = (a) => { const p = parseAddr(a); return toAddr(p.col, p.row); };

// Parses every formula cell; returns { asts, deps } where deps maps a formula cell to its distinct referenced addresses.
function analyze(sheet) {
  const asts = new Map(), deps = new Map();
  for (const [addr, raw] of sheet.cells) {
    if (!raw.startsWith("=")) continue;
    let ast = null;
    try { ast = parseFormula(raw.slice(1)); } catch { ast = null; }
    asts.set(addr, ast);
    const refs = new Set();
    if (ast) for (const r of refsOf(ast)) { try { refs.add(norm(r)); } catch { /* ignore */ } }
    deps.set(addr, [...refs]);
  }
  return { asts, deps };
}

// Iterative Tarjan over formula cells (edge: cell -> referenced formula cell).
// Returns SCCs, each after every SCC it depends on, and the set of cells on a cycle.
function components(deps) {
  const index = new Map(), low = new Map(), onStack = new Set(), stack = [];
  const sccs = [], cyclic = new Set();
  let counter = 0;
  for (const root of deps.keys()) {
    if (index.has(root)) continue;
    const work = [[root, 0]];
    index.set(root, counter); low.set(root, counter++); stack.push(root); onStack.add(root);
    while (work.length) {
      const frame = work[work.length - 1];
      const [v] = frame;
      const out = deps.get(v);
      if (frame[1] < out.length) {
        const w = out[frame[1]++];
        if (!deps.has(w)) continue;
        if (!index.has(w)) {
          index.set(w, counter); low.set(w, counter++); stack.push(w); onStack.add(w);
          work.push([w, 0]);
        } else if (onStack.has(w)) low.set(v, Math.min(low.get(v), index.get(w)));
      } else {
        work.pop();
        if (work.length) { const u = work[work.length - 1][0]; low.set(u, Math.min(low.get(u), low.get(v))); }
        if (low.get(v) === index.get(v)) {
          const comp = [];
          let w;
          do { w = stack.pop(); onStack.delete(w); comp.push(w); } while (w !== v);
          sccs.push(comp);
          if (comp.length > 1 || out.includes(v)) for (const c of comp) cyclic.add(c);
        }
      }
    }
  }
  return { sccs, cyclic };
}

export function computeAll(sheet) {
  const values = new Map();
  for (const [addr, raw] of sheet.cells) if (!raw.startsWith("=")) values.set(addr, valueOf(raw));
  const { asts, deps } = analyze(sheet);
  const { sccs, cyclic } = components(deps);
  const lookup = (a) => {
    let key;
    try { key = norm(a); } catch { return "#REF!"; }
    return values.has(key) ? values.get(key) : null;
  };
  for (const comp of sccs) {
    for (const addr of comp) {
      const ast = asts.get(addr);
      if (cyclic.has(addr)) values.set(addr, "#CYCLE!");
      else if (!ast) values.set(addr, "#ERROR!");
      else values.set(addr, evaluate(ast, lookup));
    }
  }
  const out = new Map();
  for (const addr of sheet.cells.keys()) out.set(addr, values.get(addr));
  return out;
}

class Heap {
  constructor() { this.a = []; }
  get size() { return this.a.length; }
  push(x) {
    const a = this.a; let i = a.push(x) - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (compareAddr(a[p], a[i]) <= 0) break;
      [a[p], a[i]] = [a[i], a[p]]; i = p;
    }
  }
  pop() {
    const a = this.a, top = a[0], last = a.pop();
    if (a.length) {
      a[0] = last; let i = 0;
      for (;;) {
        let m = i; const l = 2 * i + 1, r = l + 1;
        if (l < a.length && compareAddr(a[l], a[m]) < 0) m = l;
        if (r < a.length && compareAddr(a[r], a[m]) < 0) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]]; i = m;
      }
    }
    return top;
  }
}

export function dependents(sheet, addr) {
  const start = norm(addr);
  const { deps } = analyze(sheet);
  const { cyclic } = components(deps);
  const readers = new Map();
  for (const [cell, refs] of deps) for (const r of refs) {
    if (!readers.has(r)) readers.set(r, []);
    readers.get(r).push(cell);
  }
  const found = new Set(), queue = [start];
  while (queue.length) {
    for (const c of readers.get(queue.pop()) ?? []) {
      if (c === start || cyclic.has(c) || found.has(c)) continue;
      found.add(c); queue.push(c);
    }
  }
  const pending = new Map(), heap = new Heap();
  for (const c of found) {
    let n = 0;
    for (const r of deps.get(c)) if (found.has(r)) n++;
    pending.set(c, n);
    if (n === 0) heap.push(c);
  }
  const result = [];
  while (heap.size) {
    const c = heap.pop();
    result.push(c);
    for (const d of readers.get(c) ?? []) {
      if (!found.has(d)) continue;
      const n = pending.get(d) - 1;
      pending.set(d, n);
      if (n === 0) heap.push(d);
    }
  }
  return result;
}
