// Number format subset: sections, 0 # , . % E+/E-, quoted text, backslash escapes.

// Plain decimal digits of a non-negative finite number as JavaScript prints it: [int, frac].
function decimalParts(abs) {
  let s = String(abs);
  const m = /^(\d+)(?:\.(\d+))?e([+-]\d+)$/.exec(s);
  if (!m) {
    const [i, f = ""] = s.split(".");
    return [i, f];
  }
  const digits = m[1] + (m[2] ?? "");
  const point = m[1].length + Number(m[3]);
  if (point <= 0) return ["0", "0".repeat(-point) + digits];
  if (point >= digits.length) return [digits + "0".repeat(point - digits.length), ""];
  return [digits.slice(0, point), digits.slice(point)];
}

function shift(int, frac, places) {
  frac = frac.padEnd(places, "0");
  return [(int + frac.slice(0, places)).replace(/^0+(?=\d)/, ""), frac.slice(places)];
}

// Increment a digit string by one, possibly growing it.
function increment(d) {
  const a = d.split("");
  let i = a.length - 1;
  while (i >= 0 && a[i] === "9") a[i--] = "0";
  if (i < 0) return "1" + a.join("");
  a[i] = String(Number(a[i]) + 1);
  return a.join("");
}

function roundDigits(int, frac, n) {
  frac = frac.padEnd(n, "0");
  if (frac.length === n) return [int, frac];
  let all = int + frac.slice(0, n);
  if (frac[n] >= "5") all = increment(all);
  return [all.slice(0, all.length - n) || "0", n ? all.slice(all.length - n) : ""];
}

function splitSections(pattern) {
  const out = [];
  let cur = "";
  for (let i = 0; i < pattern.length; i++) {
    const c = pattern[i];
    if (c === '"') {
      const j = pattern.indexOf('"', i + 1);
      const end = j < 0 ? pattern.length : j + 1;
      cur += pattern.slice(i, end);
      i = end - 1;
    } else if (c === "\\") {
      cur += pattern.slice(i, i + 2);
      i++;
    } else if (c === ";") {
      out.push(cur);
      cur = "";
    } else cur += c;
  }
  out.push(cur);
  return out;
}

function tokenize(section) {
  const toks = [];
  for (let i = 0; i < section.length; i++) {
    const c = section[i];
    if (c === '"') {
      const j = section.indexOf('"', i + 1);
      const end = j < 0 ? section.length : j;
      toks.push({ t: "lit", v: section.slice(i + 1, end) });
      i = end;
    } else if (c === "\\") {
      if (i + 1 < section.length) toks.push({ t: "lit", v: section[i + 1] });
      i++;
    } else if ((c === "E" || c === "e") && (section[i + 1] === "+" || section[i + 1] === "-")) {
      let j = i + 2;
      let zeros = 0;
      while (section[j] === "0" || section[j] === "#") {
        if (section[j] === "0") zeros++;
        j++;
      }
      toks.push({ t: "exp", plus: section[i + 1] === "+", zeros, v: c });
      i = j - 1;
    } else if (c === "0" || c === "#") toks.push({ t: "dig", zero: c === "0" });
    else if (c === "," || c === "." || c === "%") toks.push({ t: c });
    else toks.push({ t: "lit", v: c });
  }
  return toks;
}

function group(s) {
  return s.replace(/\B(?=(\d{3})+$)/g, ",");
}

// Formats abs (>= 0). Returns { text, zero }.
function render(abs, section) {
  const toks = tokenize(section);
  const dot = toks.findIndex((k) => k.t === ".");
  const expTok = toks.find((k) => k.t === "exp");
  const isInt = (k, idx) => k.t === "dig" && (dot < 0 || idx < dot);
  const expIdx = toks.indexOf(expTok);
  const isFrac = (k, idx) => k.t === "dig" && dot >= 0 && idx > dot && (expIdx < 0 || idx < expIdx);
  const intToks = toks.filter(isInt);
  const fracToks = toks.filter(isFrac);
  const n = fracToks.length;
  const intZeros = intToks.filter((k) => k.zero).length;
  const lastZero = fracToks.map((k) => k.zero).lastIndexOf(true);
  const percents = toks.filter((k) => k.t === "%").length;

  let [int, frac] = decimalParts(abs);
  if (percents) [int, frac] = shift(int, frac, 2 * percents);
  int = int.replace(/^0+(?=\d)/, "");

  let exp = 0;
  let expText = "";
  if (expTok) {
    const all = (int + frac).replace(/^0+/, "");
    if (all === "") {
      int = "0";
      frac = "0".repeat(n);
    } else {
      exp = int !== "0" ? int.length - 1 : -(frac.length - frac.replace(/^0+/, "").length + 1);
      let [i, f] = roundDigits(all[0], all.slice(1), n);
      if (i.length > 1) {
        exp++;
        f = (i.slice(1) + f).slice(0, n);
        i = i[0];
      }
      int = i;
      frac = f;
    }
    const e = String(Math.abs(exp)).padStart(expTok.zeros, "0");
    expText = expTok.v + (exp < 0 ? "-" : expTok.plus ? "+" : "") + e;
  } else [int, frac] = roundDigits(int, frac, n);

  const zero = /^0*$/.test(int + frac);
  let intStr = int === "0" || /^0+$/.test(int) ? "" : int;
  intStr = intStr.padStart(intZeros, "0");
  const grouped = toks.some((k, idx) => {
    if (k.t !== ",") return false;
    return toks.slice(0, idx).some((x, j) => isInt(x, j)) && toks.slice(idx).some((x, j) => isInt(x, j + idx));
  });
  if (grouped) intStr = group(intStr);
  let fracStr = frac;
  while (fracStr.length > lastZero + 1 && fracStr.endsWith("0")) fracStr = fracStr.slice(0, -1);

  let out = "";
  let intDone = false;
  let fracDone = false;
  toks.forEach((k, idx) => {
    if (k.t === "lit") out += k.v;
    else if (k.t === "%") out += "%";
    else if (k.t === "exp") out += expText;
    else if (k.t === "dig") {
      if (isInt(k, idx) && !intDone) out += intStr, (intDone = true);
      else if (isFrac(k, idx) && !fracDone) out += fracStr, (fracDone = true);
    } else if (k.t === ".") {
      if (!intDone) out += intStr, (intDone = true);
      out += ".";
    }
  });
  if (!intDone && dot < 0 && !toks.some((k) => k.t === "lit" && false)) {
    // pattern without placeholders: nothing to show
  }
  return { text: out, zero };
}

export function formatNumber(value, pattern) {
  if (value === null || value === undefined) return "";
  if (typeof value === "boolean") return value ? "TRUE" : "FALSE";
  if (typeof value !== "number") return String(value);
  if (/^general$/i.test(pattern)) return String(value);
  if (!Number.isFinite(value)) return String(value);
  const sections = splitSections(pattern);
  const neg = value < 0 || Object.is(value, -0) ? value < 0 : false;
  const abs = Math.abs(value);
  if (sections.length === 1) {
    const r = render(abs, sections[0]);
    return neg && !r.zero ? "-" + r.text : r.text;
  }
  if (neg) return render(abs, sections[1]).text;
  if (value === 0 && sections.length >= 3) return render(abs, sections[2]).text;
  return render(abs, sections[0]).text;
}
