// CSV import and export for sheets.
import { createSheet, setCell, getCell, cellAddrs } from "./sheet.mjs";
import { parseAddr, toAddr } from "./addr.mjs";

const text = (v) => (v == null ? "" : v === true ? "TRUE" : v === false ? "FALSE" : String(v));

const quote = (s) => (/[,"\n\r]/.test(s) || s.startsWith(" ") || s.endsWith(" ") ? `"${s.replace(/"/g, '""')}"` : s);

export function toCSV(sheet, values) {
  const addrs = cellAddrs(sheet);
  if (!addrs.length) return "";
  let rows = 0, cols = 0;
  for (const a of addrs) {
    const p = parseAddr(a);
    rows = Math.max(rows, p.row + 1);
    cols = Math.max(cols, p.col + 1);
  }
  let out = "";
  for (let r = 0; r < rows; r++) {
    const fields = [];
    for (let c = 0; c < cols; c++) {
      const a = toAddr(c, r);
      fields.push(quote(values ? text(values.get(a)) : getCell(sheet, a)));
    }
    out += fields.join(",") + "\n";
  }
  return out;
}

function detectDelimiter(src) {
  const counts = { ",": 0, ";": 0, "\t": 0 };
  let inQ = false;
  for (let i = 0; i < src.length; i++) {
    const ch = src[i];
    if (ch === '"') inQ = !inQ;
    else if (!inQ) {
      if (ch === "\n" || ch === "\r") break;
      if (ch in counts) counts[ch]++;
    }
  }
  let best = ",";
  for (const d of [";", "\t"]) if (counts[d] > counts[best]) best = d;
  return best;
}

export function fromCSV(src, options = {}) {
  const delim = options.delimiter ?? detectDelimiter(src);
  const sheet = createSheet();
  const put = (row, col, f) => {
    if (f === "") return;
    if (!options.formulas && f.startsWith("=")) f = "'" + f;
    setCell(sheet, toAddr(col, row), f);
  };
  let row = 0, col = 0, i = 0, line = 1;
  const n = src.length;
  while (i < n) {
    let field = "";
    if (src[i] === '"') {
      const startLine = line;
      i++;
      for (;;) {
        if (i >= n) throw new Error(`unclosed quote at line ${startLine}`);
        const ch = src[i];
        if (ch === '"') {
          if (src[i + 1] === '"') { field += '"'; i += 2; continue; }
          i++;
          break;
        }
        if (ch === "\n") line++;
        field += ch;
        i++;
      }
    }
    while (i < n && src[i] !== "\n" && !src.startsWith(delim, i) && !(src[i] === "\r" && src[i + 1] === "\n")) {
      field += src[i++];
    }
    put(row, col, field);
    if (i >= n) break;
    if (src.startsWith(delim, i)) { i += delim.length; col++; if (i >= n) break; continue; }
    i += src[i] === "\r" ? 2 : 1;
    line++; row++; col = 0;
  }
  return sheet;
}
