// Row/column insertion and deletion, rewriting formula references to follow the moved cells.
import { parseAddr, toAddr, colName, colIndex } from "./addr.mjs";

// Maps one index along an axis; returns null if the cell was deleted.
function mapIndex(i, op) {
  if (op.insert) return i >= op.at ? i + op.count : i;
  if (i < op.at) return i;
  if (i >= op.at + op.count) return i - op.count;
  return null;
}

// Maps an inclusive span along an axis; returns null if it was deleted entirely.
function mapSpan(s, e, op) {
  if (op.insert) return [s >= op.at ? s + op.count : s, e >= op.at ? e + op.count : e];
  const end = op.at + op.count;
  if (op.at <= s && end - 1 >= e) return null;
  const ns = s >= end ? s - op.count : s >= op.at ? op.at : s;
  const ne = e >= end ? e - op.count : e >= op.at ? op.at - 1 : e;
  return [ns, ne];
}

const fmt = (a, col, row) => `${a.colAbs ? "$" : ""}${colName(col)}${a.rowAbs ? "$" : ""}${row + 1}`;
const REF = "(\\$?[A-Za-z]+\\$?\\d+)";
const TOKEN = new RegExp(`"(?:[^"]|"")*"|(?<![A-Za-z0-9_.])${REF}(?::${REF})?(?![A-Za-z0-9_.(])`, "g");

function rewriteRef(text, op) {
  const a = parseAddr(text);
  const r = op.axis === "row" ? mapIndex(a.row, op) : mapIndex(a.col, op);
  if (r === null) return null;
  return op.axis === "row" ? fmt(a, a.col, r) : fmt(a, r, a.row);
}

function rewriteRange(t1, t2, op) {
  const a = parseAddr(t1), b = parseAddr(t2);
  const k = op.axis === "row" ? "row" : "col";
  const lo = Math.min(a[k], b[k]), hi = Math.max(a[k], b[k]);
  const m = mapSpan(lo, hi, op);
  if (!m) return null;
  const first = a[k] <= b[k] ? 0 : 1;
  const na = { ...a, [k]: m[first] }, nb = { ...b, [k]: m[1 - first] };
  return `${fmt(na, na.col, na.row)}:${fmt(nb, nb.col, nb.row)}`;
}

function rewriteFormula(raw, op) {
  return raw.replace(TOKEN, (m, r1, r2) => {
    if (m[0] === '"') return m;
    try {
      const out = r2 ? rewriteRange(r1, r2, op) : rewriteRef(r1, op);
      return out ?? "#REF!";
    } catch {
      return m;
    }
  });
}

function apply(sheet, op) {
  const next = new Map();
  for (const [addr, raw] of sheet.cells) {
    const a = parseAddr(addr);
    const r = mapIndex(op.axis === "row" ? a.row : a.col, op);
    if (r === null) continue;
    const key = op.axis === "row" ? toAddr(a.col, r) : toAddr(r, a.row);
    next.set(key, raw.startsWith("=") ? rewriteFormula(raw, op) : raw);
  }
  sheet.cells = next;
}

const rowOp = (insert, at, count) => ({ axis: "row", insert, at: at - 1, count });
const colOp = (insert, at, count) => ({ axis: "col", insert, at: colIndex(at), count });

export const insertRows = (sheet, at, count = 1) => apply(sheet, rowOp(true, at, count));
export const deleteRows = (sheet, at, count = 1) => apply(sheet, rowOp(false, at, count));
export const insertCols = (sheet, at, count = 1) => apply(sheet, colOp(true, at, count));
export const deleteCols = (sheet, at, count = 1) => apply(sheet, colOp(false, at, count));
