// Table operations: sorting a range of rows and pivoting computed values.
import { parseAddr, toAddr, compareAddr } from "./addr.mjs";
import { getCell, setCell } from "./sheet.mjs";
import { valueOf } from "./recalc.mjs";

function parseRange(range) {
  const [a, b = a] = range.split(":");
  const p = parseAddr(a), q = parseAddr(b);
  return { c1: Math.min(p.col, q.col), c2: Math.max(p.col, q.col), r1: Math.min(p.row, q.row), r2: Math.max(p.row, q.row) };
}

const isEmpty = (v) => v === null || v === undefined || v === "";
const rank = (v) => (typeof v === "number" ? 0 : typeof v === "boolean" ? 2 : 1);

// Orders non-empty values: numbers, then strings (case-insensitive), then booleans (false first).
function compareValues(a, b) {
  const ra = rank(a), rb = rank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 0) return a - b;
  if (ra === 2) return Number(a) - Number(b);
  const x = String(a).toLowerCase(), y = String(b).toLowerCase();
  return x < y ? -1 : x > y ? 1 : 0;
}

export function sortRange(sheet, range, keys, options = {}) {
  const { c1, c2, r1, r2 } = parseRange(range);
  const start = options.header ? r1 + 1 : r1;
  const rows = [];
  for (let r = start; r <= r2; r++) {
    const raws = [];
    for (let c = c1; c <= c2; c++) raws.push(getCell(sheet, toAddr(c, r)));
    rows.push({ raws, vals: raws.map(valueOf) });
  }
  const specs = (keys ?? []).map((k) => ({ i: parseAddr(`${k.col}1`).col - c1, desc: !!k.desc }));
  rows.sort((x, y) => {
    for (const { i, desc } of specs) {
      const a = x.vals[i], b = y.vals[i];
      const ea = isEmpty(a), eb = isEmpty(b);
      if (ea || eb) {
        if (ea && eb) continue;
        return ea ? 1 : -1;
      }
      const d = compareValues(a, b);
      if (d) return desc ? -d : d;
    }
    return 0;
  });
  rows.forEach((row, n) => row.raws.forEach((raw, j) => setCell(sheet, toAddr(c1 + j, start + n), raw)));
}

export function pivot(values, range, { rows, value, agg }) {
  const { c1, c2, r1, r2 } = parseRange(range);
  const names = new Map();
  for (let c = c1; c <= c2; c++) {
    const n = values.get(toAddr(c, r1));
    if (!isEmpty(n) && !names.has(String(n))) names.set(String(n), c);
  }
  for (const name of [rows, value]) {
    if (!names.has(name)) throw new Error(`pivot: no column named ${name}`);
  }
  const kc = names.get(rows), vc = names.get(value);
  const groups = new Map();
  let blank = null;
  for (let r = r1 + 1; r <= r2; r++) {
    const k = values.get(toAddr(kc, r)) ?? null;
    const v = values.get(toAddr(vc, r)) ?? null;
    let g;
    if (isEmpty(k)) g = blank ??= { key: "(blank)", vals: [] };
    else {
      g = groups.get(k);
      if (!g) groups.set(k, (g = { key: k, vals: [] }));
    }
    g.vals.push(v);
  }
  const out = [...groups.values()].sort((a, b) => compareValues(a.key, b.key));
  if (blank) out.push(blank);
  return out.map(({ key, vals }) => {
    const nums = vals.filter((v) => typeof v === "number");
    let res;
    if (agg === "count") res = vals.filter((v) => !isEmpty(v)).length;
    else if (agg === "sum") res = nums.reduce((s, n) => s + n, 0);
    else if (!nums.length) res = null;
    else if (agg === "avg") res = nums.reduce((s, n) => s + n, 0) / nums.length;
    else if (agg === "min") res = Math.min(...nums);
    else if (agg === "max") res = Math.max(...nums);
    else throw new Error(`pivot: unknown aggregate ${agg}`);
    return { key, value: res };
  });
}
